def family_init(ctx):
    """Volume profile bucketed onto the OPTION STRIKE LATTICE, not into
    arbitrary price bins. The grid level that has absorbed the most volume
    over the trailing sessions is the proxy for the largest open-interest
    strike; in the run-up to monthly expiry price is pulled toward it."""
    import calendar
    bars = ctx.bars
    m = len(bars)

    cal = {}

    def month(y, mo):
        k = (y, mo)
        if k not in cal:
            nd = calendar.monthrange(y, mo)[1]
            fri = 0
            mar = 0
            nov = 0
            cf = 0
            for d in range(1, nd + 1):
                if calendar.weekday(y, mo, d) == 4:
                    cf += 1
                    if cf == 3:
                        fri = d
                        break
            # US DST runs 2nd Sunday of March -> 1st Sunday of November
            cn = 0
            for d in range(1, calendar.monthrange(y, 3)[1] + 1):
                if calendar.weekday(y, 3, d) == 6:
                    cn += 1
                    if cn == 2:
                        mar = d
                        break
            for d in range(1, calendar.monthrange(y, 11)[1] + 1):
                if calendar.weekday(y, 11, d) == 6:
                    nov = d
                    break
            wk = [d for d in range(1, nd + 1) if calendar.weekday(y, mo, d) < 5]
            cal[k] = (fri, mar, nov, wk)
        return cal[k]

    def gsize(p):
        s = float(ctx.p.g_scale)
        if p < 20.0:
            g = 0.5
        elif p < 100.0:
            g = 1.0
        elif p < 200.0:
            g = 2.5
        else:
            g = 5.0
        return g * s

    # ---- per-bar calendar fields, session ids, ET minute ----
    sid = [0] * m
    etm = [0] * m
    rank = [0] * m          # weekdays from this date to expiry, inclusive
    order = []
    seen = {}
    for i in range(m):
        t = bars[i]["t"]
        y = int(t[0:4]); mo = int(t[5:7]); d = int(t[8:10])
        hh = int(t[11:13]); mi = int(t[14:16])
        fri, mar, nov, wk = month(y, mo)
        on = ((mo > 3 or (mo == 3 and d >= mar))
              and (mo < 11 or (mo == 11 and d < nov)))
        etm[i] = hh * 60 + mi + (-240 if on else -300)
        dte = t[:10]
        if dte not in seen:
            seen[dte] = len(order)
            order.append(dte)
        sid[i] = seen[dte]
        r = 0
        if fri and d <= fri and calendar.weekday(y, mo, d) < 5:
            for x in wk:
                if d <= x <= fri:
                    r += 1
        rank[i] = r

    daily = len(order) == m
    ns = len(order)

    # ---- each session's own (typical price, volume) pairs ----
    own = [[] for _ in range(ns)]
    close = [None] * ns
    for i in range(m):
        k = sid[i]
        tp = (float(bars[i]["h"]) + float(bars[i]["l"])
              + float(bars[i]["c"])) / 3.0
        own[k].append((tp, float(bars[i].get("v") or 0.0)))
        close[k] = float(bars[i]["c"])

    # ---- profile for each session, built ONLY from earlier sessions ----
    lb = max(1, int(ctx.p.prof_n))
    prof = [None] * ns
    for k in range(ns):
        if k == 0:
            continue
        g = gsize(close[k - 1])
        acc = {}
        for j in range(max(0, k - lb), k):
            for tp, v in own[j]:
                b = int(round(tp / g))
                acc[b] = acc.get(b, 0.0) + v
        prof[k] = (g, acc)
    ctx.prof = prof
    ctx.sid = sid

    # ---- the trading window: the W weekday sessions ending on expiry ----
    w = max(1, int(ctx.p.win_days))
    eh = int(ctx.p.entry_hour) * 60
    act = [False] * m
    for i in range(m):
        r = rank[i]
        if r < 1 or r > w:
            continue
        e = 960 if daily else etm[i]
        if r == w:
            act[i] = e >= eh          # first day: not before the entry hour
        elif r == 1:
            act[i] = e <= 958         # expiry Friday: out by 15:58 ET
        else:
            act[i] = True
    ctx.act = ctx.series(act, "expiry_window")


def _kstar(ctx, i):
    k = ctx.sid[i]
    p = ctx.prof[k]
    if p is None:
        return None, None
    g, acc = p
    if not acc or g <= 0.0:
        return None, None
    px = ctx.c[i]
    lv = int(round(px / g))
    r = max(1, int(ctx.p.radius))
    best = None
    bv = -1.0
    for j in range(lv - r, lv + r + 1):
        v = acc.get(j, 0.0)
        if v > bv:
            bv = v
            best = j
    if best is None or bv <= 0.0:
        return None, None
    return best * g, g


def signal(ctx, i):
    if not ctx.act[i]:
        return 0
    ks, g = _kstar(ctx, i)
    if ks is None:
        return 0
    d = ctx.c[i] - ks
    t = ctx.p.trig_g * g
    if d <= -t:
        return 1
    if d >= t:
        return -1
    return 0


def exit_signal(ctx, i):
    if not ctx.positions:
        return False
    if not ctx.act[i]:
        return True
    ks, g = _kstar(ctx, i)
    if ks is None:
        return True
    px = ctx.c[i]
    if abs(px - ks) <= ctx.p.targ_g * g:
        return True
    p = ctx.positions[0]
    d = 1.0 if p["side"] == "long" else -1.0
    if (px - p["entry"]) * d <= -ctx.p.stop_g * g:
        return True
    return False
